    if (\$r->StartTime && \$r->EndTime) {
        try {
            \$s = \Carbon\Carbon::createFromFormat('H:i:s', substr(\$r->StartTime,0,8));
            \$e = \Carbon\Carbon::createFromFormat('H:i:s', substr(\$r->EndTime,0,8));
