                \$e = \Carbon\Carbon::createFromFormat('H:i:s', substr(\$cs->EndTime,0,8));
                if (\$e > \$s) \$hours = \$e->diffInMinutes(\$s) / 60.0;
            } catch (\Exception \$ex) {}
        }
        \$buckets[\$tid]['tutoring'] += \$hours;
        echo '  Session#' . \$cs->id . ' Teacher=' . \$tid . ' Date=' . \$cs->SessionDate . ' ' . \$cs->StartTime . '-' . \$cs->EndTime . ' hours=' . \$hours . PHP_EOL;
